  trips: [{ n: "Berseba → Bethel (op de vlucht)", s: 0 }, { n: "Bethel → Haran", s: 1 }, { n: "Haran → Gilead (stiekem weg)", s: 4 }, { n: "Hebron → Gosen in Egypte", s: 12 }, { n: "Alles wat Jakob reisde", s: "alles" }],
